//! Command results and their conversion to CLI output.

use std::io::Write;

/// A command's output text or its original failure.
///
/// Render the response once at the CLI boundary. Text is written verbatim.
///
/// ```
/// use exposed::inbound::cli::IntoResponse;
///
/// let mut output = Vec::new();
/// "Finished\n".into_response().write_to(&mut output)?;
/// assert_eq!(output, b"Finished\n");
/// # Ok::<(), anyhow::Error>(())
/// ```
pub struct Response(anyhow::Result<String>);

impl Response {
    /// Write successful output without adding a newline.
    ///
    /// # Errors
    /// Returns the original command error or an error from the writer.
    pub fn write_to(self, mut writer: impl Write) -> anyhow::Result<()> {
        writer.write_all(self.0?.as_bytes())?;
        Ok(())
    }
}

/// Convert a command's return value to CLI output.
///
/// Unit values are silent. Strings are written verbatim. Results preserve errors
/// and convert successful values through their own implementation.
///
/// Command-specific output types can choose their text representation.
///
/// ```
/// use exposed::inbound::cli::{IntoResponse, Response};
///
/// struct Imported(usize);
///
/// impl IntoResponse for Imported {
///     fn into_response(self) -> Response {
///         format!("Imported {} records\n", self.0).into_response()
///     }
/// }
///
/// let result: anyhow::Result<Imported> = Ok(Imported(3));
/// let mut output = Vec::new();
/// result.into_response().write_to(&mut output)?;
/// assert_eq!(output, b"Imported 3 records\n");
/// # Ok::<(), anyhow::Error>(())
/// ```
pub trait IntoResponse {
    /// Convert this value to a response for the CLI boundary.
    fn into_response(self) -> Response;
}

impl IntoResponse for Response {
    fn into_response(self) -> Response {
        self
    }
}

impl IntoResponse for () {
    fn into_response(self) -> Response {
        String::new().into_response()
    }
}

impl IntoResponse for String {
    fn into_response(self) -> Response {
        Response(Ok(self))
    }
}

impl IntoResponse for &str {
    fn into_response(self) -> Response {
        self.to_owned().into_response()
    }
}

impl<T, E> IntoResponse for Result<T, E>
where
    T: IntoResponse,
    E: Into<anyhow::Error>,
{
    fn into_response(self) -> Response {
        match self {
            Ok(value) => value.into_response(),
            Err(error) => Response(Err(error.into())),
        }
    }
}

#[cfg(test)]
mod tests {
    use std::io;

    use super::*;

    fn render(value: impl IntoResponse) -> Vec<u8> {
        let mut output = Vec::new();
        value.into_response().write_to(&mut output).unwrap();
        output
    }

    #[test]
    fn unit_is_silent_and_strings_are_verbatim() {
        assert!(render(()).is_empty());
        assert_eq!(render("hello"), b"hello");
        assert_eq!(render("first\nsecond\n".to_owned()), b"first\nsecond\n");
        assert_eq!(render(""), b"");
    }

    #[test]
    fn custom_results_and_responses_use_their_conversion() {
        struct Count(usize);
        impl IntoResponse for Count {
            fn into_response(self) -> Response {
                format!("Count: {}\n", self.0).into_response()
            }
        }
        assert_eq!(render(Ok::<_, io::Error>(Count(3))), b"Count: 3\n");
        assert_eq!(render("text".into_response()), b"text");
        assert!(render(Ok::<_, io::Error>(())).is_empty());
    }

    #[test]
    fn command_error_preserves_type_and_context_without_output() {
        let error = anyhow::Error::new(io::Error::new(io::ErrorKind::NotFound, "missing run"))
            .context("loading declarations");
        let result: anyhow::Result<String> = Err(error);
        let mut output = Vec::new();
        let error = result.into_response().write_to(&mut output).unwrap_err();
        assert!(output.is_empty());
        assert_eq!(error.to_string(), "loading declarations");
        assert_eq!(error.root_cause().to_string(), "missing run");
        assert_eq!(error.downcast_ref::<io::Error>().unwrap().kind(), io::ErrorKind::NotFound);
    }

    #[test]
    fn writer_failure_is_returned() {
        struct Broken;
        impl Write for Broken {
            fn write(&mut self, _: &[u8]) -> io::Result<usize> {
                Err(io::Error::new(io::ErrorKind::BrokenPipe, "closed output"))
            }
            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }
        let error = "text".into_response().write_to(Broken).unwrap_err();
        assert_eq!(error.downcast_ref::<io::Error>().unwrap().kind(), io::ErrorKind::BrokenPipe);
    }
}
